CREATE POLICY "tenants_readable_by_their_group" ON "pharmacy"."tenants" AS PERMISSIVE FOR SELECT TO public USING (id = any(string_to_array(nullif(current_setting('app.readable_tenant_ids', true), ''), ',')::uuid[]));--> statement-breakpoint
ALTER POLICY "tenant_memberships_of_active_tenant_or_account" ON "pharmacy"."tenant_memberships" TO public USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid or account_id = nullif(current_setting('app.account_id', true), '') or current_setting('app.is_platform', true) = 'on') WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid or current_setting('app.is_platform', true) = 'on');--> statement-breakpoint
ALTER POLICY "tenants_of_active_tenant_or_account" ON "pharmacy"."tenants" TO public USING (id = nullif(current_setting('app.tenant_id', true), '')::uuid or id in (select tenant_id from pharmacy.tenant_memberships where account_id = nullif(current_setting('app.account_id', true), '')) or current_setting('app.is_platform', true) = 'on') WITH CHECK (id = nullif(current_setting('app.tenant_id', true), '')::uuid or current_setting('app.is_platform', true) = 'on');